import csv

# The prompt says CATALOG_CSV and VALUES_CSV are already defined.
# Let's try to use them directly.

ts_basement = 'urn:buildgraph:tsref:7a9e6dea-7214-57d7-a3ab-6fec741ab22a'
ts_datacenter = 'urn:buildgraph:tsref:e1a79a88-2d8b-57bd-bf62-59a3912057c5'
target_time = '2018-01-14 16:00'

def get_value(ts_id, timestamp):
    try:
        with open(VALUES_CSV, 'r') as f:
            reader = csv.reader(f)
            next(reader) # skip header
            for row in reader:
                if row[0] == ts_id and row[1] == timestamp:
                    return float(row[2])
    except NameError:
        return "VALUES_CSV not defined"
    except FileNotFoundError:
        return "File not found"
    return None

val_basement = get_value(ts_basement, target_time)
val_datacenter = get_value(ts_datacenter, target_time)

print(f"Basement: {val_basement}")
print(f"DataCenter: {val_datacenter}")
